"""Compile locally reviewed published species summaries; no raw book text in Assets."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[2]
rows = [line.split('\t') for line in Path(__file__).with_name('expanded-species.tsv').read_text(encoding='utf-8').splitlines() if line]
assert all(len(row) == 4 for row in rows)
assert len({row[0] for row in rows}) == len(rows)
q = lambda value: json.dumps(value, ensure_ascii=False)
code = ['// Generated by tools/character-data/build-expanded-species.py.', 'namespace Taruck.CharacterCreation { public static class CharacterExpandedSpeciesText {', 'internal static string Get(string key) { switch(key) {']
code += ['case ' + q(key) + ': return ' + q(ua) + ';' for key, ua, _, _ in rows]
code += ['default: throw new System.ArgumentException("Unknown species text: " + key);', '} }', 'public static readonly string[] Templates = {' + ', '.join(q(ua) for _, ua, _, _ in rows if '{' in ua) + '};', '} }']
(root / 'Assets/Skripts/Domain/CharacterExpandedSpeciesText.cs').write_text('\n'.join(code) + '\n', encoding='utf-8')
p = root / 'Assets/Resources/Localization.txt'
existing = p.read_text(encoding='utf-8-sig')
known = {line.split('\t')[0] for line in existing.splitlines()}
extra = ['\t'.join(row[1:]) for row in rows if row[1] not in known]
if extra:
    p.write_text(existing.rstrip('\n') + '\n' + '\n'.join(extra) + '\n', encoding='utf-8')
source = json.loads((root / 'tools/character-data/cache/data/races.json').read_text(encoding='utf-8'))
wanted = {('Tabaxi', 'MPMM'), ('Kenku', 'MPMM'), ('Goblin', 'MPMM'), ('Kalashtar', 'ERLW'), ('Kalashtar', 'EFA'), ('Dhampir', 'VRGR'), ('Astral Elf', 'AAG'), ('Bugbear', 'MPMM'), ('Hobgoblin', 'MPMM'), ('Changeling', 'MPMM'), ('Changeling', 'EFA'), ('Harengon', 'MPMM'), ('Owlin', 'SCC'), ('Leonin', 'MOT'), ('Aarakocra', 'MPMM'), ('Fairy', 'MPMM'), ('Firbolg', 'MPMM'), ('Giff', 'AAG'), ('Hadozee', 'AAG'), ('Plasmoid', 'AAG'), ('Centaur', 'MPMM'), ('Minotaur', 'MPMM'), ('Satyr', 'MPMM'), ('Sea Elf', 'MPMM'), ('Kender', 'DSotDQ'), ('Verdan', 'AI'), ('Deep Gnome', 'MPMM'), ('Duergar', 'MPMM'), ('Githyanki', 'MPMM'), ('Githzerai', 'MPMM'), ('Hexblood', 'VRGR'), ('Reborn', 'VRGR'), ('Triton', 'MPMM'), ('Yuan-Ti', 'MPMM'), ('Genasi', 'MPMM'), ('Eladrin', 'MPMM'), ('Shadar-Kai', 'MPMM'), ('Kobold', 'MPMM'), ('Shifter', 'MPMM'), ('Shifter', 'EFA'), ('Lizardfolk', 'MPMM'), ('Tortle', 'MPMM'), ('Locathah', 'LR'), ('Loxodon', 'GGR'), ('Autognome', 'AAG'), ('Thri-kreen', 'AAG'), ('Vedalken', 'GGR'), ('Simic Hybrid', 'GGR'), ('Dragonborn (Chromatic)', 'FTD'), ('Dragonborn (Metallic)', 'FTD'), ('Dragonborn (Gem)', 'FTD'), ('Khoravar', 'EFA'), ('Orc', 'MPMM'), ('Aasimar', 'MPMM'), ('Goliath', 'MPMM'), ('Lupin', 'RHW'), ('Lorwyn Changeling', 'LFL'), ('Rimekin', 'LFL')}
records = [record for record in source['race'] if (record['name'], record['source']) in wanted]
assert len(records) == len(wanted)
(root / 'tools/character-data/expanded-species-sources.json').write_text(json.dumps({'pinnedCommit': '8790755429c346d20020eed7826d312d484c393f', 'selected': [{k: r[k] for k in ('name', 'source', 'page', 'lineage', 'edition') if k in r} for r in records]}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

subraces=[r for r in source["subrace"] if r.get("raceName")=="Genasi" and r["source"]=="MPMM"]
assert len(subraces)==4
manifest=root / "tools/character-data/expanded-species-sources.json"
metadata=json.loads(manifest.read_text(encoding="utf-8"))
metadata["subraces"]=[{k:r[k] for k in ("name","source","raceName","raceSource","page") if k in r} for r in subraces]
manifest.write_text(json.dumps(metadata,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
